#!/usr/bin/env bash
# Self-verifying apply script for CP360 AI Operations Brain Phases 1-3.
# Safe to run multiple times. Refuses to run unless it detects it's sitting
# in the actual deckarc-latest repo root, so it cannot land files in the
# wrong place the way the last two manual tar extractions did.
set -euo pipefail

if [ ! -f package.json ] || ! grep -q '"name": "vite-react-typescript-starter"' package.json 2>/dev/null; then
  echo "ERROR: this does not look like the deckarc-latest repo root." >&2
  echo "cd into the directory that directly contains package.json, src/, and supabase/, then re-run this script." >&2
  exit 1
fi
if [ ! -d src/lib ] || [ ! -d supabase/migrations ]; then
  echo "ERROR: src/lib or supabase/migrations not found here — wrong directory." >&2
  exit 1
fi

echo "Repo root confirmed: $(pwd)"

# Clean up debris from the previous mis-extraction, if present.
if [ -d cp360phase1phase2 ]; then
  echo "Removing stray cp360phase1phase2/ directory from a prior bad extraction..."
  rm -rf cp360phase1phase2
fi
if [ -f "docs/ai-brain/ADR-CP360-AI-001_CANONICAL_SYSTEM.md.md" ]; then
  echo "Removing double-.md ADR file..."
  rm -f "docs/ai-brain/ADR-CP360-AI-001_CANONICAL_SYSTEM.md.md" "docs/ai-brain/ADR-CP360-AI-002_LEAN_INFRASTRUCTURE.md.md"
fi

echo "Extracting Phase 1-3 payload..."
base64 -d <<'PAYLOAD_EOF' | tar -xzf -

PAYLOAD_EOF

echo ""
echo "Done. Verifying key files landed correctly:"
for f in package.json src/lib/aiBrain/registry.ts src/lib/aiBrain/sops/tradeMaterialCoordination.ts src/lib/scheduleEngine.ts supabase/migrations/20260814090000_add_trade_material_coordination_sop.sql; do
  if [ -f "$f" ]; then
    echo "  OK   $f"
  else
    echo "  MISSING  $f"
  fi
done

echo ""
echo "Next steps:"
echo "  git add -A -- docs/ai-brain/ package.json src/lib/ supabase/migrations/"
echo "  git status   # review what's staged"
echo "  git commit -m 'CP360 AI Operations Brain: Phases 1-3'"
echo "  git push origin claude/cp360-ai-phase0-discovery-3vtkij"
